:root {
  --card-bg: #0d2b45;
  --card-border: #1a4a6e;
  --header-bg: #0a2038;
  --footer-bg: #0a2038;
  --accent-teal: #00c9b1;
  --accent-orange: #ff7043;
  --accent-yellow: #ffd54f;
  --text-primary: #e8f4f8;
  --text-secondary: #7fb8d4;
  --badge-bg: #00c9b1;
  --badge-text: #0d2b45;
  --stat-bg: #0f3356;
  --stat-border: #1a4a6e;
  --tag-bg: #1a4a6e;
  --tag-text: #7fb8d4;
  --dot-active: #00c9b1;
  --dot-inactive: #1a4a6e;
  --status-color: #69f0ae;
}

.card {
  width: 480px;
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 16px;
  overflow: hidden;
  margin: 0 auto;
}

.card-header {
  background-color: var(--header-bg);
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 14px;
  border-bottom: 2px solid var(--card-border);
}

.tank-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 4px 10px;
  border-radius: 6px;
  flex-shrink: 0;
}

.header-title {
  flex: 1;
}

.species-name {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.scientific-name {
  font-size: 12px;
  color: var(--text-secondary);
  font-style: italic;
  margin: 2px 0 0 0;
}

.status-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: var(--status-color);
  flex-shrink: 0;
}

.card-body {
  padding: 16px 18px;
  display: flex;
  gap: 16px;
  align-items: stretch;
}

.visual-block {
  width: 100px;
  background-color: var(--stat-bg);
  border: 1px solid var(--stat-border);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 8px;
  flex-shrink: 0;
}

.fish-icon {
  font-size: 40px;
  line-height: 1;
}

.origin-tag {
  font-size: 10px;
  font-weight: 700;
  color: var(--accent-teal);
  letter-spacing: 0.05em;
  text-align: center;
  text-transform: uppercase;
}

.stats-grid {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.stat-item {
  background-color: var(--stat-bg);
  border: 1px solid var(--stat-border);
  border-radius: 8px;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.stat-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.stat-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
}

.card-footer {
  background-color: var(--footer-bg);
  border-top: 2px solid var(--card-border);
  padding: 12px 18px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.compat-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  white-space: nowrap;
  flex-shrink: 0;
}

.compat-tags {
  flex: 1;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.tag {
  background-color: var(--tag-bg);
  color: var(--tag-text);
  font-size: 11px;
  font-weight: 600;
  padding: 3px 9px;
  border-radius: 20px;
  border: 1px solid var(--card-border);
}

.care-level {
  display: flex;
  gap: 5px;
  align-items: center;
  flex-shrink: 0;
}

.care-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--dot-inactive);
}

.care-dot.active {
  background-color: var(--dot-active);
}
